package com.mavric.health.portal;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import com.mavric.health.identity.Access;
import com.mavric.health.shared.*;
import com.mavric.health.scheduling.application.SchedulingService;
import com.mavric.health.scheduling.domain.Requests.Reserve;
@Service
public class PortalService {
    private final com.mavric.health.persistence.sqlserver.SqlServerPortalDocumentStore store;
    private final com.mavric.health.persistence.sqlserver.SqlServerPortalAppointmentStore appointmentStore;
    private final com.mavric.health.persistence.sqlserver.SqlServerPortalPatientsStore patientsStore;
    private final com.mavric.health.persistence.sqlserver.SqlServerPortalBalanceStore balanceStore;
    private final Sql sql;private final Access access;private final SchedulingService scheduling;
    @org.springframework.beans.factory.annotation.Autowired
    public PortalService(Sql sql,Access access,SchedulingService scheduling) { this.sql=sql;this.access=access;this.scheduling=scheduling;this.store=null;this.appointmentStore=null;this.patientsStore=null;this.balanceStore=null; }
    /** Explicit partial selection: only documents uses the store; other paths retain their collaborators. */
    public PortalService(com.mavric.health.persistence.sqlserver.SqlServerPortalDocumentStore store,Sql sql,Access access,SchedulingService scheduling){this.store=java.util.Objects.requireNonNull(store);this.sql=sql;this.access=access;this.scheduling=scheduling;this.appointmentStore=null;this.patientsStore=null;this.balanceStore=null;}
    /** Explicit selection of both migrated reads; all other paths retain their legacy collaborators. */
    public PortalService(com.mavric.health.persistence.sqlserver.SqlServerPortalDocumentStore store,com.mavric.health.persistence.sqlserver.SqlServerPortalAppointmentStore appointmentStore,Sql sql,Access access,SchedulingService scheduling){this.store=java.util.Objects.requireNonNull(store);this.appointmentStore=java.util.Objects.requireNonNull(appointmentStore);this.sql=sql;this.access=access;this.scheduling=scheduling;this.patientsStore=null;this.balanceStore=null;}
    /** Explicit selection of the three migrated reads; reserve and balance retain their collaborators. */
    public PortalService(com.mavric.health.persistence.sqlserver.SqlServerPortalDocumentStore store,com.mavric.health.persistence.sqlserver.SqlServerPortalAppointmentStore appointmentStore,com.mavric.health.persistence.sqlserver.SqlServerPortalPatientsStore patientsStore,Sql sql,Access access,SchedulingService scheduling){this.store=java.util.Objects.requireNonNull(store);this.appointmentStore=java.util.Objects.requireNonNull(appointmentStore);this.patientsStore=java.util.Objects.requireNonNull(patientsStore);this.sql=sql;this.access=access;this.scheduling=scheduling;this.balanceStore=null;}
    /** Explicit selection of the four migrated portal reads; reserve still delegates to scheduling. */
    public PortalService(com.mavric.health.persistence.sqlserver.SqlServerPortalDocumentStore store,com.mavric.health.persistence.sqlserver.SqlServerPortalAppointmentStore appointmentStore,com.mavric.health.persistence.sqlserver.SqlServerPortalPatientsStore patientsStore,com.mavric.health.persistence.sqlserver.SqlServerPortalBalanceStore balanceStore,Sql sql,Access access,SchedulingService scheduling){this.store=java.util.Objects.requireNonNull(store);this.appointmentStore=java.util.Objects.requireNonNull(appointmentStore);this.patientsStore=java.util.Objects.requireNonNull(patientsStore);this.balanceStore=java.util.Objects.requireNonNull(balanceStore);this.sql=sql;this.access=access;this.scheduling=scheduling;}
    private void portal() { access.roles("PAC","RES"); access.module("PORTAL"); }
    public Object patients() { if(patientsStore!=null){portal();var req=com.mavric.health.audit.TraceContext.REQUEST.get();if(req==null)throw new ApiException(500,"DATABASE_ERROR","No se pudo completar la operacion de datos.");var actor=access.actor();Object host=req.getAttribute("health.tenant");if(host!=null && !(host instanceof com.mavric.health.tenancy.TenantRef))throw new ApiException(500,"DATABASE_ERROR","No se pudo completar la operacion de datos.");if(!actor.equals(req.getAttribute("health.actor")) || !(host instanceof com.mavric.health.tenancy.TenantRef tenant) || actor.tenantId()==null || !actor.tenantId().equals(tenant.id()))throw ApiException.forbidden();return patientsStore.patients(req);} portal(); return sql.rows("SELECT p.id,p.name,p.domain,p.birth_date,p.species,l.relationship,l.scopes FROM patients p JOIN patient_links l ON l.tenant_id=p.tenant_id AND l.patient_id=p.id WHERE p.tenant_id=? AND l.user_id=? AND l.active ORDER BY p.name",access.tenantId(),access.userId()); }
    @Transactional public Object documents(String id) { if(store!=null){portal();var req=com.mavric.health.audit.TraceContext.REQUEST.get();if(req==null)throw new ApiException(500,"DATABASE_ERROR","No se pudo completar la operacion de datos.");var actor=access.actor();Object host=req.getAttribute("health.tenant");if(host!=null && !(host instanceof com.mavric.health.tenancy.TenantRef))throw new ApiException(500,"DATABASE_ERROR","No se pudo completar la operacion de datos.");if(!actor.equals(req.getAttribute("health.actor")) || !(host instanceof com.mavric.health.tenancy.TenantRef tenant) || actor.tenantId()==null || !actor.tenantId().equals(tenant.id()))throw ApiException.forbidden();return store.documents(req,Checks.id(id));} portal(); access.link(Checks.id(id),"DOCUMENTS"); var result=sql.rows("SELECT id,title,type,content,revision,signer_id,signed_at,content_hash,original_id FROM documents WHERE tenant_id=? AND patient_id=? AND published AND NOT withdrawn AND status='SIGNED' ORDER BY signed_at DESC LIMIT 200",access.tenantId(),id); sql.call("sp_audit",access.tenantId(),access.userId(),"PORTAL_DOCUMENTS_READ",id,sql.json(java.util.Map.of())); return result; }
    public Object appointments(String id) { if(appointmentStore!=null){portal();var req=com.mavric.health.audit.TraceContext.REQUEST.get();if(req==null)throw new ApiException(500,"DATABASE_ERROR","No se pudo completar la operacion de datos.");var actor=access.actor();Object host=req.getAttribute("health.tenant");if(host!=null && !(host instanceof com.mavric.health.tenancy.TenantRef))throw new ApiException(500,"DATABASE_ERROR","No se pudo completar la operacion de datos.");if(!actor.equals(req.getAttribute("health.actor")) || !(host instanceof com.mavric.health.tenancy.TenantRef tenant) || actor.tenantId()==null || !actor.tenantId().equals(tenant.id()))throw ApiException.forbidden();return appointmentStore.appointments(req,Checks.id(id));} portal(); access.link(Checks.id(id),"APPOINTMENTS"); return sql.rows("SELECT id,branch_id,professional_id,specialty_code,starts_at,ends_at,status,service,revision FROM appointments WHERE tenant_id=? AND patient_id=? ORDER BY starts_at DESC LIMIT 200",access.tenantId(),id); }
    public Object reserve(Reserve p,String key) { portal(); return scheduling.reserve(p,key,true); }
    public Object balance(String id) { if(balanceStore!=null){portal();access.module("FINANCE");var req=com.mavric.health.audit.TraceContext.REQUEST.get();if(req==null)throw new ApiException(500,"DATABASE_ERROR","No se pudo completar la operacion de datos.");var actor=access.actor();Object host=req.getAttribute("health.tenant");if(host!=null && !(host instanceof com.mavric.health.tenancy.TenantRef))throw new ApiException(500,"DATABASE_ERROR","No se pudo completar la operacion de datos.");if(!actor.equals(req.getAttribute("health.actor")) || !(host instanceof com.mavric.health.tenancy.TenantRef tenant) || actor.tenantId()==null || !actor.tenantId().equals(tenant.id()))throw ApiException.forbidden();return balanceStore.balance(req,Checks.id(id));} portal(); access.module("FINANCE"); access.link(Checks.id(id),"BILLING"); return sql.one("SELECT COALESCE(SUM(IF(kind='PAYMENT',-amount_minor,amount_minor)),0) balance_minor,'PEN' currency FROM finance_movements WHERE tenant_id=? AND patient_id=?",access.tenantId(),id); }
}
